/// Control behavior of formatting emails
pub struct DiffFormatEmailOptions {
    raw: raw::git_diff_format_email_options,
}

/// Control behavior of formatting emails
pub struct DiffPatchidOptions {
    raw: raw::git_diff_patchid_options,
